PY=$(cat graphify-out/.graphify_python 2>/dev/null || echo python3) && $PY -c "
import json
from collections import defaultdict
g=json.load(open('graphify-out/graph.json'))
nodes={n['id']:n for n in g['nodes']}
edges=g['links']

call_rels={'calls','indirect_call'}
inbound=defaultdict(set)      # target -> set of distinct source callers
inbound_all=defaultdict(int)  # target -> raw edge count
for e in edges:
    if e.get('relation') in call_rels:
        t=e['target']; s=e['source']
        inbound[t].add(s)
        inbound_all[t]+=1

def internal(nid):
    n=nodes.get(nid); 
    return n and str(n.get('source_file','')).startswith('internal/')

rows=[]
for t,callers in inbound.items():
    if internal(t):
        rows.append((len(callers), inbound_all[t], t))
rows.sort(reverse=True)
print('Top fan-in (distinct callers / raw edges) for internal/ targets:')
for distinct,raw,t in rows[:15]:
    n=nodes[t]
    print(f'{distinct:4d} distinct / {raw:4d} raw  {n[\"label\"]:35s} {n[\"source_file\"]}:{n[\"source_location\"]}  id={t}')
"
